<script setup>
import '../../../css/team.css';
import { computed, ref, onMounted, onBeforeUnmount, nextTick, watch } from 'vue';
import { router, useForm } from '@inertiajs/vue3';
import { ArrowPathIcon, CalendarDaysIcon, ChevronLeftIcon, ChevronRightIcon, UserPlusIcon, UsersIcon, AdjustmentsHorizontalIcon, ExclamationTriangleIcon, ClockIcon, XMarkIcon, ArrowTopRightOnSquareIcon } from '@heroicons/vue/24/outline';
import AppSelect from '@/Components/Product/AppSelect.vue';
import AppDialog from '@/Components/Product/AppDialog.vue';
import SearchField from '@/Components/Product/SearchField.vue';
import AppButton from '@/Components/Product/AppButton.vue';
import PageHeader from '@/Components/Product/PageHeader.vue';
import PhoneInput from '@/Components/Product/PhoneInput.vue';
import FormField from '@/Components/Product/FormField.vue';
import AppLayout from '@/Layouts/AppLayout.vue';
import StaffProfileDrawer from '@/Components/Team/StaffProfileDrawer.vue';
import AccessPanel from '@/Components/Team/AccessPanel.vue';
import { dayNames, matchesStaff, staffDay, shiftRules, durationLabel, initialName, localDate, timelineStyle, coverage, isTimeOff, ruleLabel, tabKey } from '@/Support/teamWorkspace';
const props=defineProps({business:Object,locations:Array,services:Array,staff:Array,readiness:Object,roleSuggestions:Array,accessRoles:Array,accessModules:Array,pendingInvitations:Array,seatAllowance:Object,canManageOwners:Boolean,activityPreview:Array,grantablePermissions:Array,accounts:Array,schedule:Object,upcomingSchedule:Object,filters:Object,updatedAt:String,incomplete:Boolean,can:Object});
const now=ref(Date.now()), search=ref(''), statusFilter=ref('active'), serviceFilter=ref(''), roleFilter=ref(''), view=ref(props.filters.view), refreshing=ref(false), refreshError=ref('');
const drawer=ref(null), addDialog=ref(null), accountDialog=ref(null), selectedAccount=ref(null), accountDirty=ref(false), accountBusy=ref(false), discardAdd=ref(false), addSearch=ref('');
const location=computed(()=>props.locations.find(l=>l.public_id===props.filters.location));
const zone=computed(()=>location.value?.time_zone || props.business.time_zone);
const today=computed(()=>localDate(now.value,zone.value));
const day=computed(()=>props.schedule.days.find(d=>d.date===props.filters.date));
const dateTitle=computed(()=>new Intl.DateTimeFormat(undefined,{timeZone:'UTC',weekday:'long',month:'short',day:'numeric'}).format(new Date(props.filters.date+'T12:00Z')));
const time=value=>value?new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit',timeZone:zone.value}).format(new Date(value)):'—';
const clock=value=>value?new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit',timeZone:'UTC'}).format(new Date(`2000-01-01T${value.slice(0,5)}:00Z`)):'Off';
const dateLabel=value=>new Intl.DateTimeFormat(undefined,{timeZone:zone.value,day:'numeric',month:'short'}).format(new Date(value));
const localDayLabel=date=>new Intl.DateTimeFormat(undefined,{timeZone:'UTC',day:'numeric',month:'short',weekday:'short'}).format(new Date(date+'T12:00Z'));
const selectedTeam=computed(()=>props.staff.filter(p=>p.locations.some(l=>l.public_id===props.filters.location)));
const states=computed(()=>Object.fromEntries(selectedTeam.value.map(p=>[p.public_id,staffDay(p,day.value,now.value,zone.value,today.value)])));
const titles=computed(()=>[...new Set(props.staff.map(p=>p.title || 'Team member'))].sort());
const visibleStaff=computed(()=>selectedTeam.value.filter(p=>{
 const s=states.value[p.public_id];return matchesStaff(p,search.value) && (!roleFilter.value || (p.title || 'Team member')===roleFilter.value)
 && (!serviceFilter.value || p.services.some(s=>s.public_id===serviceFilter.value && s.is_qualified && s.is_active && s.locations.includes(props.filters.location)))
 && (!statusFilter.value || (statusFilter.value==='active'?p.status==='active':statusFilter.value==='inactive'?p.status!=='active':statusFilter.value==='working'?s.working:statusFilter.value==='available'?s.available:statusFilter.value==='attention'?s.conflicts>0 || s.state==='overrun':statusFilter.value==='off'?!s.working:statusFilter.value===s.state));
}));
const stats=computed(()=>({working:selectedTeam.value.filter(p=>states.value[p.public_id].working).length,available:selectedTeam.value.filter(p=>states.value[p.public_id].available).length,break:selectedTeam.value.filter(p=>states.value[p.public_id].state==='break').length,off:selectedTeam.value.filter(p=>p.status==='active' && !states.value[p.public_id].working).length}));
const attention=computed(()=>selectedTeam.value.filter(p=>states.value[p.public_id].conflicts || states.value[p.public_id].state==='overrun'));
const stale=computed(()=>now.value-Date.parse(props.updatedAt)>120000);
const clear=()=>{search.value='';roleFilter.value='';serviceFilter.value='';statusFilter.value='active';};
const calendarUrl=(staff=null)=>route('business.calendar',{business:props.business.public_id,location:props.filters.location,date:props.filters.date,...(staff?{staff:[staff]}:{}),view:'staff'});
const urlSelection=(staff=null)=>{const url=new URL(window.location.href);url.searchParams.set('view',view.value);if(staff)url.searchParams.set('staff',staff);else url.searchParams.delete('staff');window.history.replaceState(window.history.state,'',url);};
const openPerson=(person,tab='overview')=>{urlSelection(person.public_id);drawer.value?.open(person.public_id,tab);};
const switchView=target=>{view.value=target;urlSelection();};
const load=(selection)=>router.get(route('business.team.index',props.business.public_id),{...props.filters,...selection,staff:null,view:view.value},{preserveState:true,preserveScroll:true,onStart:()=>refreshing.value=true,onFinish:()=>refreshing.value=false});
const shiftDate=delta=>{const d=new Date(props.filters.date+'T12:00Z');d.setUTCDate(d.getUTCDate()+delta);load({date:d.toISOString().slice(0,10)});};
const refresh=(manual=false)=>{
 if(refreshing.value || document.visibilityState!=='visible' || (!manual && document.querySelector('dialog[open]')) || (!manual && (document.querySelector('.tm-more[open]') || document.activeElement?.closest('input,select,textarea,[role=combobox]'))))return;
 router.reload({only:['staff','schedule','upcomingSchedule','updatedAt','pendingInvitations','accounts','incomplete'],preserveScroll:true,onStart:()=>refreshing.value=true,onSuccess:()=>refreshError.value='',onError:()=>refreshError.value='Could not refresh. The current schedule remains visible.',onNetworkError:()=>{refreshError.value='Connection lost. Refresh when you reconnect.';return false;},onFinish:()=>refreshing.value=false});
};
let clockTimer,pollTimer;
onMounted(()=>{clockTimer=setInterval(()=>now.value=Date.now(),15000);pollTimer=setInterval(()=>refresh(),30000);if(props.filters.staff){const p=props.staff.find(p=>p.public_id===props.filters.staff);if(p)openPerson(p);} });
onBeforeUnmount(()=>{clearInterval(clockTimer);clearInterval(pollTimer);});
const shifts=(p,d=props.filters.date)=>shiftRules(p,d,location.value?.id);
const shiftText=(p,d=props.filters.date)=>shifts(p,d).map(r=>`${clock(r.starts_at)}–${clock(r.ends_at)}`).join(' · ') || 'Off';
const visitCount=p=>p.appointments.filter(a=>localDate(Date.parse(a.starts_at),zone.value)===props.filters.date).length;
const nextVisit=p=>p.appointments.find(a=>localDate(Date.parse(a.starts_at),zone.value)>=props.filters.date && (props.filters.date!==today.value || Date.parse(a.starts_at)>now.value) && a.status!=='completed');
const statusDetail=p=>{const s=states.value[p.public_id];if(s.state==='overrun')return 'Review the running visit';if(s.state==='soon')return `Next at ${time(s.next?.startsAt)} · ${s.gapMinutes}m free`;if(s.available)return `${s.gapMinutes}m free${s.next?' · next '+time(s.next.startsAt):''}`;if(s.state==='leave' && s.context.unavailable.some(u=>isTimeOff(u) && (Date.parse(u.endsAt)-Date.parse(u.startsAt))>=23*60*60000))return 'Off for the day';if(s.until)return `${s.state==='later'?'From':'Until'} ${time(s.until)}`;return shifts(p).length?'No bookable time':'No working hours';};
const skills=p=>p.services.filter(s=>s.is_qualified && s.is_active && s.locations.includes(props.filters.location));
const visibleIds=computed(()=>visibleStaff.value.filter(p=>p.status==='active').map(p=>p.public_id));
const dayStats=d=>d.staff.filter(s=>visibleIds.value.includes(s.id) && s.windows.length);
const dayCoverage=d=>coverage(d,visibleIds.value);
const leave=computed(()=>visibleStaff.value.flatMap(p=>p.availability.filter(r=>isTimeOff(r) && r.starts_on && (r.ends_on || r.starts_on)>=props.filters.date && (!r.location_id || r.location_id===location.value?.id)).map(r=>({person:p,rule:r}))).sort((a,b)=>a.rule.starts_on.localeCompare(b.rule.starts_on)));
const defaultRole=props.accessRoles.find(r=>r.name==='barber_stylist') || props.accessRoles[0];
const form=useForm({display_name:'',email:'',mobile:'',title:'',online_visible:true,location:props.filters.location || props.locations[0]?.public_id || '',service_ids:[],working_days:[],starts_at:'09:00',ends_at:'18:00',invite_access:false,access_role_id:defaultRole?.id || null,custom_access:false,permission_names:[]});
const addClose=()=>{if(form.processing)return false;if(form.isDirty){discardAdd.value=true;return false;}return true;};
const openAdd=async()=>{form.reset();form.location=props.filters.location || props.locations[0]?.public_id || '';form.clearErrors();discardAdd.value=false;addSearch.value='';await addDialog.value?.open();await nextTick();document.getElementById('team-add-name')?.focus();};
const save=()=>form.post(route('business.team.providers.store',props.business.public_id),{preserveScroll:true,onSuccess:()=>{form.defaults();addDialog.value?.close();refresh(true);}});
const addServices=computed(()=>props.services.filter(s=>s.locations.includes(form.location) && s.name.toLocaleLowerCase().includes(addSearch.value.toLocaleLowerCase())));
const cancelInvitation=i=>router.delete(route('staff-invitations.destroy',[props.business.public_id,i.public_id]),{data:{reason:'Invitation cancelled from Team access.'},preserveScroll:true});
const openAccount=account=>{selectedAccount.value={public_id:account.public_id,display_name:account.user_name,email:account.email,has_login:account.status==='active',membership:account,locations:[]};accountDirty.value=false;accountDialog.value?.open();};
const invitationFor=p=>props.pendingInvitations.find(i=>i.staff_id===p.public_id);
watch(()=>props.filters.date,()=>{if(props.filters.date!==today.value && ['available','break','leave'].includes(statusFilter.value))statusFilter.value='active';});
const closeAccount=()=>{if(!accountDirty.value && !accountBusy.value)accountDialog.value?.close();};
const weeklyLabel=(p,d)=>{const c=d.staff.find(s=>s.id===p.public_id);return !c?.windows.length && c?.unavailable.some(isTimeOff)?'Time off':shiftText(p,d.date);};
const tabs=computed(()=>[{key:'team',label:'Team'},{key:'week',label:'Weekly coverage'},{key:'leave',label:'Time off'},...(props.can.manage?[{key:'access',label:'Access'}]:[])]);
</script>
<template>
 <AppLayout title="Team & availability" :business-label="business.name"><div class="tm-workspace">
  <PageHeader title="Team & availability"><template #actions><AppButton v-if="can.calendar && location" variant="quiet" :href="calendarUrl()"><CalendarDaysIcon class="size-4" />Calendar</AppButton><AppButton v-if="can.manage" :disabled="!seatAllowance.can_add || !locations.length" @click="openAdd"><UserPlusIcon class="size-4" />Add team member</AppButton></template></PageHeader>
  <div class="tm-toolbar"><div class="tm-location"><label for="team-location">Location</label><AppSelect id="team-location" :model-value="filters.location" class="cd-input" :disabled="refreshing" @update:model-value="load({location:$event})"><option v-for="l in locations" :key="l.public_id" :value="l.public_id">{{ l.name }}</option></AppSelect></div><div><label for="team-date">{{ view==='week'?'Week containing':'Working day' }}</label><div class="tm-date"><button type="button" class="tm-icon-button" :disabled="refreshing" aria-label="Previous working day" @click="shiftDate(view==='week'?-7:-1)"><ChevronLeftIcon /></button><input id="team-date" type="date" :value="filters.date" class="cd-input" :disabled="refreshing" @change="($event)=>{if($event.target.value)load({date:$event.target.value});}" /><button type="button" class="tm-icon-button" :disabled="refreshing" aria-label="Next working day" @click="shiftDate(view==='week'?7:1)"><ChevronRightIcon /></button><AppButton variant="quiet" size="small" @click="load({date:today})">Today</AppButton></div></div><div class="tm-zone"><p class="tm-meta">{{ zone }}</p><p class="tm-meta">{{ stale?'Availability needs refresh':'Updated '+time(updatedAt) }}</p></div><button type="button" class="tm-icon-button" :disabled="refreshing" aria-label="Refresh workforce availability" @click="refresh(true)"><ArrowPathIcon :class="{'animate-spin':refreshing}" /></button></div>
  <p v-if="refreshError" role="alert" class="tm-error mb-4">{{ refreshError }}</p><p v-if="incomplete" class="tm-attention">This week exceeds the appointment display limit. Review the full Calendar before making assignment decisions.</p>
  <div v-if="location" class="tm-strip" aria-label="Workforce summary"><button type="button" class="tm-stat" @click="statusFilter='working';switchView('team')"><strong>{{ stats.working }}</strong><span>Working {{ filters.date===today?'today':'this day' }}<small>{{ selectedTeam.filter(p=>p.status==='active').length }} active team members</small></span></button><button type="button" class="tm-stat" :disabled="filters.date!==today || stale" @click="statusFilter='available';switchView('team')"><strong>{{ filters.date===today && !stale?stats.available:'—' }}</strong><span>Available now<small>{{ filters.date===today?'Free staff time · check service fit':'Choose today for live availability' }}</small></span></button><button type="button" class="tm-stat" :disabled="filters.date!==today" @click="statusFilter='break';switchView('team')"><strong>{{ filters.date===today?stats.break:'—' }}</strong><span>On break<small>{{ filters.date===today?'Unavailable for booking':'Breaks appear in weekly coverage' }}</small></span></button><button type="button" class="tm-stat" @click="statusFilter='off';switchView('team')"><strong>{{ stats.off }}</strong><span>Off {{ filters.date===today?'today':'this day' }}<small>Time off or no bookable hours</small></span></button></div>
  <div v-if="attention.length" class="tm-attention"><ExclamationTriangleIcon /><span><strong>{{ attention.length }} {{ attention.length===1?'person needs':'people need' }} attention.</strong> Appointments outside availability or a service running over.</span><button type="button" @click="statusFilter='attention';switchView('team')">Review</button></div>
  <div class="tm-tabs" role="tablist" aria-label="Team workspace sections"><button v-for="t in tabs" :id="`team-tab-${t.key}`" :key="t.key" type="button" role="tab" :aria-selected="view===t.key" :tabindex="view===t.key?0:-1" @keydown="tabKey($event,tabs.map(t=>t.key),view,switchView,'team-tab-')" :aria-controls="`team-panel-${t.key}`" @click="switchView(t.key)">{{ t.label }}<span v-if="t.key==='team'">{{ selectedTeam.length }}</span></button></div>
  <div :id="`team-panel-${view}`" class="tm-board" role="tabpanel" :aria-labelledby="`team-tab-${view}`" :aria-busy="refreshing">
   <div v-if="view!=='access'" class="tm-filters"><SearchField v-model="search" label="Find a team member" placeholder="Name, role, branch or service" /><div class="tm-filter"><label for="team-status">Show</label><AppSelect id="team-status" v-model="statusFilter" class="cd-input"><option value="active">Active team</option><option value="">Everyone</option><option value="working">Working this day</option><option value="available" :disabled="filters.date!==today || stale">Available now</option><option value="break">On break</option><option value="leave">On leave</option><option value="off">Off / not scheduled</option><option value="attention">Needs attention</option><option value="inactive">Inactive team</option></AppSelect></div><div class="tm-filter"><label for="team-service">Can perform</label><AppSelect id="team-service" v-model="serviceFilter" class="cd-input"><option value="">All services</option><option v-for="s in services.filter(s=>s.locations.includes(filters.location))" :key="s.public_id" :value="s.public_id">{{ s.name }}</option></AppSelect></div><details class="tm-more"><summary><AdjustmentsHorizontalIcon />Filters</summary><div class="tm-more-panel"><div class="tm-filter"><label for="team-title">Professional role</label><AppSelect id="team-title" v-model="roleFilter" class="cd-input"><option value="">All roles</option><option v-for="t in titles" :key="t" :value="t">{{ t }}</option></AppSelect></div><button type="button" class="tm-text-button" @click="clear">Reset filters</button></div></details></div>
   <div v-if="!locations.length" class="tm-empty"><CalendarDaysIcon /><h2>No location yet</h2><p>Add a location before configuring the team’s working hours.</p><AppButton v-if="can.manage" :href="route('business.locations.index',business.public_id)" variant="secondary">Set up a location</AppButton></div>
   <div v-else-if="!selectedTeam.length" class="tm-empty"><UsersIcon /><h2>No team members at this location yet</h2><p>Add a person, then assign their services and working hours. Login access is optional.</p><AppButton v-if="can.manage" :disabled="!seatAllowance.can_add" @click="openAdd">Add team member</AppButton></div>
   <template v-else-if="view==='team'">
    <div v-if="!visibleStaff.length" class="tm-empty"><UsersIcon /><h2>No team members match</h2><p>Try another name, service or availability filter.</p><AppButton variant="secondary" @click="clear">Reset filters</AppButton></div>
    <div v-else class="tm-table-wrap"><table class="tm-table"><caption class="ds-sr-only">Workforce for {{ dateTitle }} at {{ location.name }}</caption><thead><tr><th scope="col">Team member</th><th scope="col" class="tm-desktop-col">Availability</th><th scope="col">Shift</th><th scope="col" class="tm-desktop-col">Reserved time</th><th scope="col" class="tm-secondary-col">Next appointment</th><th scope="col"><span class="ds-sr-only">Open profile</span></th></tr></thead><tbody><tr v-for="p in visibleStaff" :key="p.public_id"><td><button type="button" class="tm-person" @click="openPerson(p)"><span class="tm-avatar" aria-hidden="true">{{ initialName(p.display_name) }}</span><span class="min-w-0"><strong>{{ p.display_name }}</strong><small>{{ p.title || 'Team member' }}<template v-if="p.status!=='active'"> · Inactive</template></small><small class="tm-skill-summary" :title="skills(p).map(s=>s.name).join(', ')">{{ skills(p).length }} services<template v-if="skills(p).length"> · {{ skills(p).slice(0,2).map(s=>s.name).join(', ') }}</template></small></span></button><div class="tm-mobile-only tm-mobile-context"><span :class="['tm-status',`tm-state-${states[p.public_id].state}`]"><i class="tm-dot" />{{ stale && filters.date===today?'Refresh availability':states[p.public_id].label }}</span><p class="tm-meta">{{ statusDetail(p) }}</p></div></td><td class="tm-desktop-col"><span :class="['tm-status',`tm-state-${states[p.public_id].state}`]"><i class="tm-dot" />{{ stale && filters.date===today?'Refresh availability':states[p.public_id].label }}</span><p class="tm-status-detail">{{ statusDetail(p) }}</p></td><td><div class="tm-shift">{{ shiftText(p) }}</div><p class="tm-meta">{{ visitCount(p) }} {{ visitCount(p)===1?'visit':'visits' }}</p><p v-if="states[p.public_id].conflicts" class="text-[10px] text-amber-700 mt-1">{{ states[p.public_id].conflicts }} need review</p></td><td class="tm-desktop-col"><div v-if="states[p.public_id].scheduledMinutes" class="tm-load"><p><span>{{ durationLabel(states[p.public_id].bookedMinutes) }} / {{ durationLabel(states[p.public_id].scheduledMinutes) }}</span><strong>{{ states[p.public_id].utilization }}%</strong></p><div class="tm-load-bar"><i :style="{width:states[p.public_id].utilization+'%'}" /></div></div><span v-else class="tm-meta">No bookable hours</span></td><td class="tm-secondary-col"><div v-if="nextVisit(p)" class="tm-next"><span>{{ time(nextVisit(p).starts_at) }}<template v-if="localDate(Date.parse(nextVisit(p).starts_at),zone)!==filters.date"> · {{ dateLabel(nextVisit(p).starts_at) }}</template></span><small>{{ nextVisit(p).client_name }}</small></div><span v-else class="tm-meta">None in the next 2 weeks</span></td><td><button type="button" class="tm-row-action" :aria-label="`Open ${p.display_name} profile`" @click="openPerson(p)"><ChevronRightIcon /></button></td></tr></tbody></table></div>
   </template>
   <template v-else-if="view==='week'">
    <div class="tm-section-header"><div>Staffing coverage <small class="block mt-1">{{ serviceFilter?'Qualified staff for the selected service':'Effective booking windows, after breaks and time off' }}</small></div><div class="tm-legend"><span><i />Working</span><span><i class="break" />Break</span><span><i class="leave" />Time off</span></div></div>
    <div v-if="!visibleStaff.length" class="tm-empty"><h2>No team members match</h2><AppButton variant="secondary" @click="clear">Reset filters</AppButton></div>
    <template v-else><div class="tm-table-wrap tm-week-wrap" tabindex="0" role="region" aria-label="Weekly staff coverage. Scroll horizontally to see every day."><div class="tm-week"><div class="tm-week-heading tm-week-person">Team member</div><div v-for="d in schedule.days" :key="d.date" :class="['tm-week-heading',{selected:d.date===filters.date}]"><span>{{ new Intl.DateTimeFormat(undefined,{timeZone:'UTC',weekday:'short'}).format(new Date(d.date+'T12:00Z')) }}</span><strong>{{ Number(d.date.slice(-2)) }}</strong><small>{{ dayStats(d).length }} working</small></div><template v-for="p in visibleStaff" :key="p.public_id"><div class="tm-week-person"><button type="button" class="tm-person" @click="openPerson(p,'schedule')"><span class="tm-avatar">{{ initialName(p.display_name) }}</span><span class="min-w-0"><strong>{{ p.display_name }}</strong><small>{{ p.title || 'Team member' }}</small></span></button></div><button v-for="d in schedule.days" :key="d.date" type="button" :class="['tm-week-cell',{selected:d.date===filters.date,off:!d.staff.find(s=>s.id===p.public_id)?.windows.length}]" :aria-label="`${p.display_name}, ${localDayLabel(d.date)}, ${shiftText(p,d.date)}. Open schedule.`" @click="openPerson(p,'schedule')"><strong>{{ weeklyLabel(p,d) }}</strong><div class="tm-mini-timeline"><i v-for="(r,i) in d.staff.find(s=>s.id===p.public_id)?.windows || []" :key="'w'+i" :style="timelineStyle(r,d.date,zone)" /><i v-for="(r,i) in d.staff.find(s=>s.id===p.public_id)?.unavailable || []" :key="'u'+i" :class="['unavailable',{leave:isTimeOff(r)}]" :style="timelineStyle(r,d.date,zone)" /></div><small>{{ d.staff.find(s=>s.id===p.public_id)?.windows.length?'Bookable windows':'No bookable time' }}</small></button></template><div class="tm-week-summary tm-week-person">Coverage<br /><small>Within opening hours</small></div><div v-for="d in schedule.days" :key="d.date" class="tm-week-summary"><strong>{{ dayStats(d).length }} staff</strong><span v-if="!d.windows.length">Location closed</span><template v-else><span v-if="dayCoverage(d).some(c=>c.count===0)" class="tm-coverage-gap">Coverage gap</span><span v-else>Coverage throughout</span><p v-for="(c,i) in dayCoverage(d).filter(c=>c.count===0).slice(0,2)" :key="i">{{ time(c.startsAt) }}–{{ time(c.endsAt) }}</p></template></div></div></div><div class="tm-phone-week"><div v-for="d in schedule.days" :key="d.date" class="tm-phone-day"><h3>{{ localDayLabel(d.date) }}<small>{{ dayStats(d).length }} working</small></h3><button v-for="p in visibleStaff" :key="p.public_id" type="button" @click="openPerson(p,'schedule')"><span>{{ p.display_name }}</span><small>{{ weeklyLabel(p,d) }}</small></button><p v-if="dayCoverage(d).some(c=>c.count===0)" class="tm-meta tm-coverage-gap">No staff scheduled: {{ dayCoverage(d).filter(c=>c.count===0).map(c=>`${time(c.startsAt)}–${time(c.endsAt)}`).join(' · ') }}</p></div></div></template>
   </template>
   <template v-else-if="view==='leave'"><div class="tm-section-header">Upcoming time off <small>From {{ localDayLabel(filters.date) }}</small></div><div v-if="!leave.length" class="tm-empty"><CalendarDaysIcon /><h2>No upcoming time off</h2><p>Open a staff profile to add full days, partial days or a date range.</p><AppButton variant="secondary" @click="switchView('team');clear()">Choose a team member</AppButton></div><div v-else class="tm-leave-list"><div v-for="(item,i) in leave" :key="i" class="tm-leave-row"><div><button type="button" class="tm-person" @click="openPerson(item.person,'schedule')"><span class="tm-avatar">{{ initialName(item.person.display_name) }}</span><span><strong>{{ item.person.display_name }}</strong><small>{{ ruleLabel(item.rule) }}</small></span></button></div><div><strong>{{ localDayLabel(item.rule.starts_on) }}<template v-if="item.rule.ends_on!==item.rule.starts_on"> – {{ localDayLabel(item.rule.ends_on) }}</template></strong><p class="tm-meta">{{ item.rule.starts_at?`${clock(item.rule.starts_at)}–${clock(item.rule.ends_at)}`:'Full day' }}</p></div><button type="button" class="tm-text-button" @click="openPerson(item.person,'schedule')">{{ item.person.can_edit?'Manage':'View' }}</button></div></div></template>
   <template v-else-if="view==='access' && can.manage"><div class="tm-section-header">Workspace access <small>Login and employment are separate</small></div><div class="tm-access-list"><div v-for="p in selectedTeam" :key="p.public_id" class="tm-account-row"><div><strong>{{ p.display_name }}</strong><p class="tm-meta">{{ p.membership?.role_label || 'Working profile without login' }} · {{ p.email || 'No email' }}</p></div><span class="tm-meta">{{ p.has_login?'Active login':p.membership?'Disabled':invitationFor(p)?invitationFor(p).expired?'Invitation expired':'Invited':'No login' }}</span><AppButton variant="quiet" size="small" :disabled="p.membership?.is_current || !p.can_edit" @click="openPerson(p,'access')">{{ p.membership?.is_current?'Your account':p.membership?'Manage access':'Invite access' }}</AppButton></div><div v-for="a in accounts" :key="a.public_id" class="tm-account-row"><div><strong>{{ a.user_name }}</strong><p class="tm-meta">{{ a.role_label }} · Login-only account</p></div><span class="tm-meta">{{ a.status==='active'?'Active login':'Disabled' }}</span><AppButton variant="quiet" size="small" :disabled="a.is_current" @click="openAccount(a)">{{ a.is_current?'Your account':'Manage access' }}</AppButton></div></div><div class="tm-section-header">Invitations <small>{{ pendingInvitations.length }} shown · latest 100, recent expired invites</small></div><div v-if="!pendingInvitations.length" class="p-5 tm-meta">No pending invitations.</div><div v-else class="tm-access-list"><div v-for="i in pendingInvitations" :key="i.public_id" class="tm-account-row"><div><strong>{{ i.person || i.email }}</strong><p class="tm-meta">{{ i.role }} · {{ i.email }}</p></div><span class="tm-meta">{{ i.expired?'Expired':'Expires '+dateLabel(i.expires_at) }}</span><button type="button" class="tm-text-button" @click="cancelInvitation(i)">Cancel invitation</button><button v-if="i.staff_id" type="button" class="tm-text-button" @click="openPerson(staff.find(p=>p.public_id===i.staff_id),'access')">Reinvite</button></div></div></template>
   <div class="tm-footer"><span v-if="can.manage">{{ seatAllowance.used }} / {{ seatAllowance.limit || 'Unlimited' }} active team seats<span v-if="!seatAllowance.can_add"> · Plan limit reached</span></span><span v-else>Schedules follow your workspace access.</span><span>Free staff time requires service and resource checks. <a v-if="can.queue" :href="route('business.walk-ins.index',{business:business.public_id,location:filters.location})">Open Walk-in Queue <span aria-hidden="true">↗</span></a><a v-else-if="can.calendar" :href="calendarUrl()">Open Calendar <span aria-hidden="true">↗</span></a></span></div>
  </div>
  <div v-if="can.audit" class="mt-4 flex justify-end"><AppButton variant="quiet" size="small" :href="route('business.activity.index',business.public_id)"><ClockIcon class="size-3.5" />Activity log</AppButton></div>
  <StaffProfileDrawer ref="drawer" :business="business" :staff="staff" :locations="locations" :services="services" :schedule="schedule" :upcoming-schedule="upcomingSchedule" :date="filters.date" :location="location" :now="now" :can="can" :roles="accessRoles" :modules="accessModules" :grantable="grantablePermissions" :can-manage-owners="canManageOwners" :updated-at="updatedAt" :invitations="pendingInvitations" @refresh="refresh(true)" @close="urlSelection()" />
  <AppDialog ref="addDialog" class="tm-drawer" drawer title="Add team member" description="Create their working profile. Services, hours and login access can be completed afterward." :can-close="addClose"><div class="tm-profile-content"><div v-if="discardAdd" class="tm-confirm-unsaved" role="alert"><span>Discard this new profile?</span><button type="button" @click="discardAdd=false">Keep editing</button><button type="button" @click="form.reset();addDialog?.close()">Discard</button></div><form id="team-add-form" class="tm-field-grid" @submit.prevent="save"><FormField id="team-add-name" label="Name" :error="form.errors.display_name" required><input id="team-add-name" v-model="form.display_name" class="cd-input" autocomplete="name" maxlength="255" /></FormField><FormField id="team-add-title" label="Professional title" :error="form.errors.title"><input id="team-add-title" v-model="form.title" class="cd-input" list="team-titles" placeholder="Barber, stylist, receptionist…" /><datalist id="team-titles"><option v-for="t in roleSuggestions" :key="t" :value="t" /></datalist></FormField><FormField id="team-add-email" label="Email" :error="form.errors.email" required><input id="team-add-email" v-model="form.email" type="email" class="cd-input" autocomplete="email" /></FormField><FormField id="team-add-phone" label="Mobile (optional)" :error="form.errors.mobile"><PhoneInput id="team-add-phone" v-model="form.mobile" :country="business.country_code" /></FormField><FormField id="team-add-location" label="Working location" :error="form.errors.location" required class="full"><AppSelect id="team-add-location" v-model="form.location" class="cd-input"><option v-for="l in locations" :key="l.public_id" :value="l.public_id">{{ l.name }} · {{ l.time_zone }}</option></AppSelect></FormField><label class="tm-check full"><input v-model="form.online_visible" type="checkbox" />Clients can choose this person online</label><details class="full"><summary class="tm-text-button cursor-pointer">Assign initial services</summary><SearchField v-model="addSearch" label="Find services" placeholder="Search services" class="mt-3" /><label v-for="s in addServices" :key="s.public_id" class="tm-check"><input v-model="form.service_ids" type="checkbox" :value="s.public_id" />{{ s.name }}</label></details><details class="full"><summary class="tm-text-button cursor-pointer">Set initial working hours</summary><p class="tm-meta mt-3">You can leave this blank and configure different hours by day in their profile.</p><div class="flex gap-3 flex-wrap mt-2"><label v-for="(name,i) in dayNames" :key="i" class="tm-check"><input v-model="form.working_days" type="checkbox" :value="i+1" />{{ name.slice(0,3) }}</label></div><div v-if="form.working_days.length" class="tm-field-grid mt-2"><label>Starts<input v-model="form.starts_at" type="time" class="cd-input" /></label><label>Ends<input v-model="form.ends_at" type="time" class="cd-input" /></label></div></details><label class="tm-check full"><input v-model="form.invite_access" type="checkbox" />Send a secure login invitation</label><FormField v-if="form.invite_access" id="team-add-role" label="Workspace role" :error="form.errors.access_role_id" class="full"><AppSelect id="team-add-role" v-model="form.access_role_id" class="cd-input"><option v-for="r in accessRoles" :key="r.id" :value="r.id" :disabled="(r.name==='owner' && !canManageOwners) || r.permission_names.some(p=>!grantablePermissions.includes(p))">{{ r.label }}</option></AppSelect><p class="tm-meta mt-2">{{ accessRoles.find(r=>r.id===form.access_role_id)?.description }} They choose their password. Invitation expires in 7 days.</p></FormField><div v-if="Object.keys(form.errors).length" class="tm-error full" role="alert"><p v-for="(e,k) in form.errors" :key="k">{{ e }}</p></div></form></div><template #footer><AppButton variant="secondary" @click="()=>{if(addClose())addDialog?.close();}">Cancel</AppButton><AppButton type="submit" form="team-add-form" :disabled="form.processing">{{ form.processing?'Saving…':form.invite_access?'Save & invite':'Create team member' }}</AppButton></template></AppDialog>
  <AppDialog ref="accountDialog" class="tm-drawer" drawer :title="selectedAccount?.display_name || 'Workspace access'" :can-close="()=>!accountDirty && !accountBusy"><div class="tm-profile-content"><AccessPanel v-if="selectedAccount" :person="selectedAccount" :business="business" :locations="locations" :roles="accessRoles" :modules="accessModules" :grantable="grantablePermissions" :can-manage-owners="canManageOwners" @dirty="accountDirty=$event" @busy="accountBusy=$event" @saved="accountDirty=false;accountDialog?.close()" /></div><template #footer><AppButton variant="secondary" @click="closeAccount">Close</AppButton><AppButton v-if="accountDirty" :disabled="accountBusy" variant="quiet" @click="accountDirty=false;accountDialog?.close()">Discard changes</AppButton></template></AppDialog>
 </div></AppLayout>
</template>
